/// <summary>
/// VM - CB754 - Excise Register
/// </summary>
public class METExiseRegisterEditReasonCode extends common
{
   
}

Method.Source:
    /// <summary>
    /// Find the record based on code
    /// </summary>
    /// <param name = "_editReasonCode">_editReasonCode</param>
    /// <param name = "_update">_update</param>
    /// <returns>METExiseRegisterEditReasonCode</returns>
    public static METExiseRegisterEditReasonCode find(METEditReasonCode  _editReasonCode,
                                     boolean     _update = false)
    {
        METExiseRegisterEditReasonCode  metExiseRegisterEditReasonCode;

        metExiseRegisterEditReasonCode.selectForUpdate(_update);

        if (_editReasonCode)
        {
            select firstonly metExiseRegisterEditReasonCode
                index ReasonCodeIdx
                where metExiseRegisterEditReasonCode.EditReasonCode == _editReasonCode;
        }

        return metExiseRegisterEditReasonCode;
    }

/// <summary>
/// Exist method
/// </summary>
/// <param name = "_editReasonCode">_editReasonCode</param>
/// <returns>boolean</returns>
public static boolean exist(METEditReasonCode  _editReasonCode)
{
    return _editReasonCode &&
           (select firstonly RecId from metExiseRegisterEditReasonCode
            where metExiseRegisterEditReasonCode.EditReasonCode == _editReasonCode).RecId != 0;
}
